CREATE TABLE IF NOT EXISTS inquiry_attachments (
  id VARCHAR(36) NOT NULL PRIMARY KEY COMMENT '附件随机 UUID，同时用于附件下载地址',
  inquiry_id BIGINT COMMENT '关联的咨询主键，未提交咨询时为空',
  original_name VARCHAR(255) COMMENT '上传文件的原始名称，用于后台展示及下载',
  extension VARCHAR(20) COMMENT '经过校验的文件扩展名',
  size BIGINT NOT NULL COMMENT '附件大小，单位为字节',
  created_at DATETIME(6) COMMENT '附件上传时间'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='咨询附件元数据，文件保存在上传目录的 inquiries 子目录';
ALTER TABLE site_inquiries MODIFY COLUMN status VARCHAR(255) COMMENT '咨询处理状态：new 待联系，contacted 已联系，closed 已完成';
ALTER TABLE site_settings MODIFY COLUMN id VARCHAR(100) NOT NULL COMMENT '官网配置标识：website 网站基础配置，contact 联系与咨询配置，capabilities 首页能力配置', MODIFY COLUMN configuration LONGTEXT NOT NULL COMMENT '配置 JSON：website 多语言文案与图片，contact 联系、咨询和私有邮件配置，capabilities 中英文能力文案、流程步骤及图标';
INSERT INTO site_settings (id, configuration) SELECT 'contact', CONVERT( USING utf8mb4) COLLATE utf8mb4_unicode_ci WHERE NOT EXISTS (SELECT 1 FROM site_settings WHERE id='contact');
INSERT INTO app_migrations (id) SELECT '2026-10-contact-inquiries-v1' WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-contact-inquiries-v1');

-- Generated by npm run db:build. Add per-language footer links without changing existing contact or mail settings.
SET NAMES utf8mb4;
START TRANSACTION;
UPDATE site_settings SET configuration = JSON_SET(configuration, '$.contact.socialLinks', CAST(CONVERT( USING utf8mb4) COLLATE utf8mb4_unicode_ci AS JSON))
WHERE id='contact' AND JSON_VALID(configuration) AND NOT JSON_CONTAINS_PATH(configuration, 'one', '$.contact.socialLinks');
INSERT INTO app_migrations (id) SELECT '2026-10-social-links-v1' WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-social-links-v1');
COMMIT;

-- Generated by npm run db:build. Add industry icons and preserve later admin edits.
SET NAMES utf8mb4;
SET @tzme_industry_icon_sql = IF(EXISTS (SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='industries' AND COLUMN_NAME='icon'), 'SELECT 1', 'ALTER TABLE industries ADD COLUMN icon VARCHAR(500) DEFAULT '''' COMMENT ''首页服务行业图标图片地址，中英文共用，支持预设图标或上传图片，空值使用通用图标''');
PREPARE tzme_industry_icon_statement FROM @tzme_industry_icon_sql;
EXECUTE tzme_industry_icon_statement;
DEALLOCATE PREPARE tzme_industry_icon_statement;
START TRANSACTION;
SET @tzme_industry_icons_done = EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-industry-icons-v1');
UPDATE industries SET icon=CONVERT(0x2f6173736574732f696e6475737472792d69636f6e732f6d696e696e672e737667 USING utf8mb4) COLLATE utf8mb4_unicode_ci WHERE id=CONVERT(0x6d696e696e67 USING utf8mb4) COLLATE utf8mb4_unicode_ci AND COALESCE(icon, '')='' AND NOT @tzme_industry_icons_done;
