UPDATE industries SET icon=CONVERT(0x2f6173736574732f696e6475737472792d69636f6e732f6d6574616c6c757267792e737667 USING utf8mb4) COLLATE utf8mb4_unicode_ci WHERE id=CONVERT(0x6d6574616c6c75726779 USING utf8mb4) COLLATE utf8mb4_unicode_ci AND COALESCE(icon, '')='' AND NOT @tzme_industry_icons_done;
UPDATE industries SET icon=CONVERT(0x2f6173736574732f696e6475737472792d69636f6e732f656e657267792e737667 USING utf8mb4) COLLATE utf8mb4_unicode_ci WHERE id=CONVERT(0x656e65726779 USING utf8mb4) COLLATE utf8mb4_unicode_ci AND COALESCE(icon, '')='' AND NOT @tzme_industry_icons_done;
UPDATE industries SET icon=CONVERT(0x2f6173736574732f696e6475737472792d69636f6e732f636f6e737472756374696f6e2e737667 USING utf8mb4) COLLATE utf8mb4_unicode_ci WHERE id=CONVERT(0x636f6e737472756374696f6e USING utf8mb4) COLLATE utf8mb4_unicode_ci AND COALESCE(icon, '')='' AND NOT @tzme_industry_icons_done;
