INSERT INTO site_content (`id`,`title_en`,`title_zh`,`category_en`,`category_zh`,`summary_en`,`summary_zh`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`image`,`status`,`show_on_home`,`home_order`,`type`,`title`,`category`,`summary`,`content`,`industry`,`industry_ids`,`date`) SELECT 'spreader','Spreaders','排土机','Mining','矿山','A spreader machine is part of a complete set of equipment for continuous open-pit coal mining. It is used in conjunction with a wire rope drag conveyor and is suitable for disposing of and stacking loose materials at open-pit mine spoil heaps and stockyards. The tail unit, as part of the spreader, comes in two types: rail-mounted and chain-track, and is used to transfer material from the conveyor to the spreader.','用于露天矿排土场和料场的散料排放与堆存，可与连续输送设备配套，按工况配置轨道式或履带式尾车。','A spreader machine is part of a complete set of equipment for continuous open-pit coal mining. It is used in conjunction with a wire rope drag conveyor and is suitable for disposing of and stacking loose materials at open-pit mine spoil heaps and stockyards. The tail unit, as part of the spreader, comes in two types: rail-mounted and chain-track, and is used to transfer material from the conveyor to the spreader.','用于露天矿排土场和料场的散料排放与堆存，可与连续输送设备配套，按工况配置轨道式或履带式尾车。','High-efficiency discharge capability: Materials can be quickly discharged to the designated location, improving operational efficiency.
Multiple tail car designs: Offers both rail-mounted and crawler-type tail cars to suit different working conditions.
Automated control: Equipped with an advanced automation system for remote monitoring and fault diagnosis.
High durability: Manufactured with high-strength materials to withstand harsh working conditions.','散料连续排放与堆存
轨道式或履带式尾车，适配不同现场条件
远程监控与故障诊断
高强度结构，适应矿山作业环境','','','/assets/tzme-products/spreader.webp','published',0,0,'products','Spreaders','Mining','A spreader machine is part of a complete set of equipment for continuous open-pit coal mining. It is used in conjunction with a wire rope drag conveyor and is suitable for disposing of and stacking loose materials at open-pit mine spoil heaps and stockyards. The tail unit, as part of the spreader, comes in two types: rail-mounted and chain-track, and is used to transfer material from the conveyor to the spreader.','A spreader machine is part of a complete set of equipment for continuous open-pit coal mining. It is used in conjunction with a wire rope drag conveyor and is suitable for disposing of and stacking loose materials at open-pit mine spoil heaps and stockyards. The tail unit, as part of the spreader, comes in two types: rail-mounted and chain-track, and is used to transfer material from the conveyor to the spreader.','mining','mining',NULL WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-official-products-v1') AND NOT EXISTS (SELECT 1 FROM site_content WHERE id='spreader');
INSERT INTO site_content (`id`,`title_en`,`title_zh`,`category_en`,`category_zh`,`summary_en`,`summary_zh`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`image`,`status`,`show_on_home`,`home_order`,`type`,`title`,`category`,`summary`,`content`,`industry`,`industry_ids`,`date`) SELECT 'bucket-wheel-excavator','Bucket wheel excavator','斗轮挖掘机','Mining','矿山','The bucket wheel excavator is composed of components such as the bucket wheel, wheel arm, counterweight arm, chassis, traveling mechanism and discharge arm. The company can customize it according to the needs of different customers to meet the construction requirements of different product performance and different working conditions.','由斗轮、斗轮臂、配重臂、底盘、行走机构及排料臂等组成，可根据开采需求、设备性能与现场工况定制。','The bucket wheel excavator is composed of components such as the bucket wheel, wheel arm, counterweight arm, chassis, traveling mechanism and discharge arm. The company can customize it according to the needs of different customers to meet the construction requirements of different product performance and different working conditions.','由斗轮、斗轮臂、配重臂、底盘、行走机构及排料臂等组成，可根据开采需求、设备性能与现场工况定制。','High-efficiency excavation capability: The high-speed rotation and large-capacity design of the bucket wheel enable highly efficient material excavation and loading.
Customized design: Bucket wheel excavators of different sizes and performance levels can be customized according to the working conditions and needs of different customers, meeting diverse construction requirements.
Intelligent control: Equipped with an advanced automatic control system, it enables remote monitoring and fault diagnosis, improving equipment operating efficiency and safety.
Environmentally friendly and energy-saving: Utilizing advanced energy-saving technologies, it reduces energy consumption and dust emissions, complying with environmental protection requirements.','斗轮连续挖掘与装载
按作业条件定制结构尺寸与性能
自动控制、远程监控与故障诊断
节能与抑尘设计','','','/assets/tzme-products/bucket-wheel-excavator.webp','published',0,0,'products','Bucket wheel excavator','Mining','The bucket wheel excavator is composed of components such as the bucket wheel, wheel arm, counterweight arm, chassis, traveling mechanism and discharge arm. The company can customize it according to the needs of different customers to meet the construction requirements of different product performance and different working conditions.','The bucket wheel excavator is composed of components such as the bucket wheel, wheel arm, counterweight arm, chassis, traveling mechanism and discharge arm. The company can customize it according to the needs of different customers to meet the construction requirements of different product performance and different working conditions.','mining','mining',NULL WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-official-products-v1') AND NOT EXISTS (SELECT 1 FROM site_content WHERE id='bucket-wheel-excavator');
INSERT INTO site_content (`id`,`title_en`,`title_zh`,`category_en`,`category_zh`,`summary_en`,`summary_zh`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`image`,`status`,`show_on_home`,`home_order`,`type`,`title`,`category`,`summary`,`content`,`industry`,`industry_ids`,`date`) SELECT 'stacker-reclaimer','Stacker and Reclaimer','堆取料机','Mining','矿山','A stacker-reclaimer is a combination of a stacker and a reclaimer, equipped with a bucket wheel arm.','将堆料与取料功能集成于一体，配置斗轮臂，面向散料料场的连续堆存与回取作业。','A stacker-reclaimer is a combination of a stacker and a reclaimer, equipped with a bucket wheel arm.','将堆料与取料功能集成于一体，配置斗轮臂，面向散料料场的连续堆存与回取作业。','Multifunctional integration: Combines stacking and reclaiming functions, reducing equipment investment and footprint.
High-precision positioning: Equipped with an advanced positioning system for precise stacking and reclaiming operations, improving operational efficiency.
Automated operation: Supports remote control and automated operation, reducing labor costs and improving operational safety.
High durability: Manufactured with high-strength materials, suitable for harsh working conditions and offering a long service life.','堆料、取料一体化，优化设备占地
定位系统辅助堆取料作业
支持远程控制与自动化运行
高强度结构，适应连续作业','','','/assets/tzme-products/stacker-reclaimer.webp','published',0,0,'products','Stacker and Reclaimer','Mining','A stacker-reclaimer is a combination of a stacker and a reclaimer, equipped with a bucket wheel arm.','A stacker-reclaimer is a combination of a stacker and a reclaimer, equipped with a bucket wheel arm.','mining','mining',NULL WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-official-products-v1') AND NOT EXISTS (SELECT 1 FROM site_content WHERE id='stacker-reclaimer');
INSERT INTO site_content (`id`,`title_en`,`title_zh`,`category_en`,`category_zh`,`summary_en`,`summary_zh`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`image`,`status`,`show_on_home`,`home_order`,`type`,`title`,`category`,`summary`,`content`,`industry`,`industry_ids`,`date`) SELECT 'crushing-station','Crushing station','破碎站','Mining','矿山','Mainly used to crush large chunks of ore into smaller pieces for easier subsequent processing or transportation.','将大块矿石破碎至后续处理或运输所需粒度，可结合物料硬度及粒径调整破碎参数。','Mainly used to crush large chunks of ore into smaller pieces for easier subsequent processing or transportation.','将大块矿石破碎至后续处理或运输所需粒度，可结合物料硬度及粒径调整破碎参数。','High-efficiency crushing capability: Utilizing advanced crushing technology, it can quickly crush large materials into the desired particle size.
Intelligent control: Equipped with an intelligent control system, it can automatically adjust crushing parameters based on material hardness and particle size.
Environmentally friendly design: Equipped with dust reduction and noise reduction devices, it reduces dust and noise pollution, meeting environmental protection requirements.
Convenient maintenance: Modular design facilitates maintenance and component replacement, reducing downtime.','大块物料破碎与粒度控制
按物料硬度及粒径调整运行参数
抑尘与降噪设计
模块化设计，便于维护与部件更换','','','/assets/tzme-products/crushing-station.webp','published',0,0,'products','Crushing station','Mining','Mainly used to crush large chunks of ore into smaller pieces for easier subsequent processing or transportation.','Mainly used to crush large chunks of ore into smaller pieces for easier subsequent processing or transportation.','mining','mining',NULL WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-official-products-v1') AND NOT EXISTS (SELECT 1 FROM site_content WHERE id='crushing-station');
INSERT INTO site_content (`id`,`title_en`,`title_zh`,`category_en`,`category_zh`,`summary_en`,`summary_zh`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`image`,`status`,`show_on_home`,`home_order`,`type`,`title`,`category`,`summary`,`content`,`industry`,`industry_ids`,`date`) SELECT 'flotation-machine','Flotation Machine','浮选机','Mining','矿山','Used in the ore dressing stage to separate minerals of different densities. It uses the principle of froth flotation to separate target minerals from the raw ore and is an important piece of equipment in the mineral processing process.','应用于矿石选矿流程，利用泡沫浮选实现目标矿物分选，并根据不同矿石特性调整运行条件。','Used in the ore dressing stage to separate minerals of different densities. It uses the principle of froth flotation to separate target minerals from the raw ore and is an important piece of equipment in the mineral processing process.','应用于矿石选矿流程，利用泡沫浮选实现目标矿物分选，并根据不同矿石特性调整运行条件。','High separation efficiency: Improved mineral separation efficiency through optimized bubble generation and mineral attachment processes.
Automated control: Equipped with an advanced automation system for real-time monitoring of the flotation process, ensuring stable product quality.
Energy saving and consumption reduction: Utilizes high-efficiency motors and optimized bubble generators to reduce energy consumption.
Strong adaptability: Can be adjusted according to the characteristics of different minerals, adapting to various ore types.','优化气泡生成与矿物附着过程
实时监测浮选过程
高效电机与气泡发生装置
适配不同矿石的分选需求','','','/assets/tzme-products/flotation-machine.webp','published',0,0,'products','Flotation Machine','Mining','Used in the ore dressing stage to separate minerals of different densities. It uses the principle of froth flotation to separate target minerals from the raw ore and is an important piece of equipment in the mineral processing process.','Used in the ore dressing stage to separate minerals of different densities. It uses the principle of froth flotation to separate target minerals from the raw ore and is an important piece of equipment in the mineral processing process.','mining','mining',NULL WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-official-products-v1') AND NOT EXISTS (SELECT 1 FROM site_content WHERE id='flotation-machine');
INSERT INTO site_content (`id`,`title_en`,`title_zh`,`category_en`,`category_zh`,`summary_en`,`summary_zh`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`image`,`status`,`show_on_home`,`home_order`,`type`,`title`,`category`,`summary`,`content`,`industry`,`industry_ids`,`date`) SELECT 'thickener','Thickener','浓密机','Mining','矿山','It is mainly used to treat the tailings from ore processing plants, recovering valuable components from the tailings through chemical flocculation.','用于选矿厂尾矿处理，通过絮凝促进固体颗粒回收，并结合自动化控制优化尾矿处理过程。','It is mainly used to treat the tailings from ore processing plants, recovering valuable components from the tailings through chemical flocculation.','用于选矿厂尾矿处理，通过絮凝促进固体颗粒回收，并结合自动化控制优化尾矿处理过程。','High-efficiency flocculation effect: Utilizes advanced flocculation technology to improve the recovery rate of solid particles in tailings.
Automated operation: Equipped with an automated control system, enabling unattended operation and reducing labor costs.
Environmentally friendly and energy-saving: Reduces tailings discharge, minimizing environmental impact, while also lowering operating costs.
Compact structure: Small footprint, facilitating installation and maintenance.','絮凝处理，提高固体颗粒回收效率
自动化运行控制
