INSERT INTO site_content (`id`,`title_en`,`title_zh`,`category_en`,`category_zh`,`summary_en`,`summary_zh`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`image`,`status`,`show_on_home`,`home_order`,`type`,`title`,`category`,`summary`,`content`,`industry`,`industry_ids`,`date`) SELECT 'factory-building-module','Steel structure factory building modules','钢结构厂房模块','Structural steel buildings','建筑钢结构','Optimize your industrial operations with our advanced Steel Structure Factory Building Modules. Engineered for durability and flexibility, our prefabricated solutions provide a rapid, cost-effective alternative to traditional construction. Utilizing high-strength structural steel, these modules offer large, column-free interior spaces ideal for manufacturing, warehousing, and assembly lines. Fully customizable to your specific load and dimensional requirements, our factory buildings are designed for longevity, seismic resistance, and quick on-site assembly, ensuring your business operates without delay.','用于制造、仓储及装配产线的预制钢结构厂房，采用高强度钢材与模块化设计，可根据空间、载荷和尺寸需求定制。','Optimize your industrial operations with our advanced Steel Structure Factory Building Modules. Engineered for durability and flexibility, our prefabricated solutions provide a rapid, cost-effective alternative to traditional construction. Utilizing high-strength structural steel, these modules offer large, column-free interior spaces ideal for manufacturing, warehousing, and assembly lines. Fully customizable to your specific load and dimensional requirements, our factory buildings are designed for longevity, seismic resistance, and quick on-site assembly, ensuring your business operates without delay.','用于制造、仓储及装配产线的预制钢结构厂房，采用高强度钢材与模块化设计，可根据空间、载荷和尺寸需求定制。','Our Steel Structure Factory Building Modules represent the pinnacle of industrial construction technology. Designed for heavy-duty applications, these structures are fabricated from premium Q235/Q355 steel with hot-dip galvanized or anti-corrosive painting for maximum lifespan.
Structural Integrity: Rigid portal frame design engineered to withstand heavy crane loads, seismic activity, and extreme weather conditions
Modular Design: Standardized components allow for easy future expansion, relocation, and layout reconfiguration.
Versatile Cladding: Options include single or sandwich panels (EPS, Rockwool, PIR) for superior insulation and soundproofing.
Speed of Construction: Pre-engineered components are fabricated off-site and delivered ready for bolted assembly, significantly reducing construction time and labor costs.
Clear Span Capability: Up to 30+ meters of column-free space to maximize production and storage efficiency.','门式刚架与大跨度空间设计
模块化构件便于扩建与布局调整
可选单层板及 EPS、岩棉或 PIR 夹芯围护板
工厂预制，现场螺栓装配
镀锌或防腐涂装，结合风荷载与抗震需求设计','','','/assets/tzme-products/factory-building-module.webp','published',0,0,'products','Steel structure factory building modules','Structural steel buildings','Optimize your industrial operations with our advanced Steel Structure Factory Building Modules. Engineered for durability and flexibility, our prefabricated solutions provide a rapid, cost-effective alternative to traditional construction. Utilizing high-strength structural steel, these modules offer large, column-free interior spaces ideal for manufacturing, warehousing, and assembly lines. Fully customizable to your specific load and dimensional requirements, our factory buildings are designed for longevity, seismic resistance, and quick on-site assembly, ensuring your business operates without delay.','Optimize your industrial operations with our advanced Steel Structure Factory Building Modules. Engineered for durability and flexibility, our prefabricated solutions provide a rapid, cost-effective alternative to traditional construction. Utilizing high-strength structural steel, these modules offer large, column-free interior spaces ideal for manufacturing, warehousing, and assembly lines. Fully customizable to your specific load and dimensional requirements, our factory buildings are designed for longevity, seismic resistance, and quick on-site assembly, ensuring your business operates without delay.','steel-structures','steel-structures,construction',NULL WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-official-products-v1') AND NOT EXISTS (SELECT 1 FROM site_content WHERE id='factory-building-module');
INSERT INTO site_content (`id`,`title_en`,`title_zh`,`category_en`,`category_zh`,`summary_en`,`summary_zh`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`image`,`status`,`show_on_home`,`home_order`,`type`,`title`,`category`,`summary`,`content`,`industry`,`industry_ids`,`date`) SELECT 'rotary-screen','Rotary screen','滚筒筛','Mining','矿山','Equipment used for material grading and screening, widely applied in industries such as mining, construction, chemical, and food processing. It separates materials through a rotating drum and screen, effectively removing impurities, grading materials, or screening products of specific particle sizes.','通过旋转滚筒与筛网完成物料分级、除杂及粒度筛选，可用于矿山、建筑、化工及食品加工等领域。','Equipment used for material grading and screening, widely applied in industries such as mining, construction, chemical, and food processing. It separates materials through a rotating drum and screen, effectively removing impurities, grading materials, or screening products of specific particle sizes.','通过旋转滚筒与筛网完成物料分级、除杂及粒度筛选，可用于矿山、建筑、化工及食品加工等领域。','High-efficiency screening capability: Utilizing optimized drum rotation speed and screen mesh size design, it can quickly separate materials of different particle sizes, improving screening efficiency.
Strong durability: The drum and screen are made of high-strength, wear-resistant materials, ensuring wear resistance, corrosion resistance, and a long service life.
Low energy consumption operation: Adopting energy-efficient motors and an optimized transmission system, it reduces energy consumption and operating costs.
Modular design allows for convenient screen replacement, low maintenance costs, and short downtime.','结合滚筒转速及筛孔尺寸优化筛分
耐磨、防腐结构
高效电机与优化传动系统
模块化筛网，便于更换维护','','','/assets/tzme-products/rotary-screen.webp','published',0,0,'products','Rotary screen','Mining','Equipment used for material grading and screening, widely applied in industries such as mining, construction, chemical, and food processing. It separates materials through a rotating drum and screen, effectively removing impurities, grading materials, or screening products of specific particle sizes.','Equipment used for material grading and screening, widely applied in industries such as mining, construction, chemical, and food processing. It separates materials through a rotating drum and screen, effectively removing impurities, grading materials, or screening products of specific particle sizes.','mining','mining,construction',NULL WHERE NOT EXISTS (SELECT 1 FROM app_migrations WHERE id='2026-10-15-official-products-v1') AND NOT EXISTS (SELECT 1 FROM site_content WHERE id='rotary-screen');
INSERT INTO site_content (`id`,`title_en`,`title_zh`,`category_en`,`category_zh`,`summary_en`,`summary_zh`,`content_en`,`content_zh`,`features_en`,`features_zh`,`specifications_en`,`specifications_zh`,`image`,`status`,`show_on_home`,`home_order`,`type`,`title`,`category`,`summary`,`content`,`industry`,`industry_ids`,`date`) SELECT 'wagon-tippler','Wagon Tippler','翻车机','Mining','矿山','Large machinery used for tipping and unloading, mainly used in railway transport to unload bulk materials such as coal, ore, grain, etc. It works by tilting the entire railcar to a certain angle, allowing the materials to be emptied from the car, thereby achieving fast and efficient unloading operations.','用于铁路运输煤炭、矿石、粮食等散货卸料，通过将铁路车辆倾转至一定角度完成卸载。','Large machinery used for tipping and unloading, mainly used in railway transport to unload bulk materials such as coal, ore, grain, etc. It works by tilting the entire railcar to a certain angle, allowing the materials to be emptied from the car, thereby achieving fast and efficient unloading operations.','用于铁路运输煤炭、矿石、粮食等散货卸料，通过将铁路车辆倾转至一定角度完成卸载。','High-efficiency unloading capacity: Capable of unloading large quantities of materials in a short time, improving operational efficiency.
